// Intended function: make claim lifecycle changes explicit events so Empire/Chronicle systems can react without the claim registry owning those systems.
#include "world/ClaimSystem.hpp"
#include <algorithm>
namespace elysium{bool ClaimRegistry::create(ClaimRecord r){if(!r.claimId||!r.beaconStableId||claims_.contains(r.claimId))return false;r.state=ClaimState::Establishing;claims_[r.claimId]=r;return true;}bool ClaimRegistry::transition(std::uint64_t id,ClaimState s,std::uint64_t t){auto i=claims_.find(id);if(i==claims_.end()||i->second.state==s)return false;auto old=i->second.state;i->second.state=s;if(s==ClaimState::Active&&!i->second.establishedTick)i->second.establishedTick=t;float d=s==ClaimState::Active?i->second.suspicionContribution:(s==ClaimState::Lost?-.25f*i->second.suspicionContribution:0.f);events_.push_back({id,i->second.systemId,old,s,d});return true;}bool ClaimRegistry::damageBeacon(std::uint64_t id,float d,std::uint64_t t){auto i=claims_.find(id);if(i==claims_.end())return false;i->second.integrity=std::max(0.f,i->second.integrity-d);if(i->second.integrity<=0)return transition(id,ClaimState::Lost,t);if(i->second.integrity<.35f)return transition(id,ClaimState::Contested,t);return true;}std::optional<ClaimRecord>ClaimRegistry::find(std::uint64_t id)const{auto i=claims_.find(id);return i==claims_.end()?std::nullopt:std::optional<ClaimRecord>(i->second);}std::vector<ClaimEvent>ClaimRegistry::drainEvents(){auto o=std::move(events_);events_.clear();return o;}}
